def compute(vars):
    old_inventory = vars["v1"]
    new_inventory = vars["v2"]
    change = new_inventory - old_inventory

    return {
        "value": change,
        "trace": {
            "old_inventory": old_inventory,
            "new_inventory": new_inventory,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
